def main():
    root = Path(__file__).resolve().parents[1]
    assert len(CASES) == 100, len(CASES)
    output = []
    for n, (category, intent, expected, literals, hazards) in enumerate(CASES, 1):
        output.append({"id": f"complex-{n:03}", "category": category, "intent": intent,
                       "expected_commands": expected, "literal_constraints": literals,
                       "review_hazards": hazards,
                       "expected_planner_status": "needs_input_or_unsupported" if category == "abstain" else "review_required",
                       "catalog": category == "cloud" or "aws s3api" in " ".join(expected),
                       "execution_permitted": False})
    assert len({r["intent"] for r in output}) == 100
    (root / "examples/complex.jsonl").write_text("".join(json.dumps(r, ensure_ascii=True, sort_keys=True) + "\n" for r in output))
    lines = ["# 100 complex scenarios", "", "These are evaluation inputs, not claims of 100 successful model generations. None are executed by watf or the test suite. Expected command scopes are retrieval references, not proof that those commands alone can satisfy the complete task.", "", "The last ten deliberately require abstention or clarification. Other scenarios also contain ambiguities which a planner should surface instead of guessing. Read every hazard. Literal constraints must survive retrieval and generation unchanged.", ""]
    for r in output:
        lines += [f"## {r['id']}: {r['category']}", "", r["intent"], "", "Reference scopes: " + ", ".join(f"`{x}`" for x in r["expected_commands"]) + ".", "", "Review: " + "; ".join(r["review_hazards"]) + ".", ""]
    (root / "examples/COMPLEX.md").write_text("\n".join(lines))
    print(f"wrote {len(output)} distinct scenarios")

if __name__ == "__main__": main()
